import { readFile, writeFile } from 'node:fs/promises';

// Keep one source of truth while the buildless homepage avoids CSS requests.
const root = new URL('../', import.meta.url);
const [html, shared, consulting] = await Promise.all([
  readFile(new URL('index.html', root), 'utf8'),
  readFile(new URL('styles.css', root), 'utf8'),
  readFile(new URL('consulting.css', root), 'utf8'),
]);
const css = `${shared}\n${consulting}`;
if (/<\/style/i.test(css)) throw new Error('Unexpected closing style tag in CSS');

const block = [
  '  <!-- HOME STYLES START: generated by scripts/sync-home-styles.mjs -->',
  '  <style id="home-styles">',
  css.trimEnd(),
  '  </style>',
  '  <!-- HOME STYLES END -->',
].join('\n');
const marker = /  <!-- HOME STYLES START:[\s\S]*?<!-- HOME STYLES END -->/;
if (!marker.test(html)) throw new Error('Homepage style markers are missing');
const updated = html.replace(marker, () => block);

if (process.argv.includes('--check')) {
  if (updated !== html) throw new Error('Run node scripts/sync-home-styles.mjs');
  console.log('Homepage styles match the shared sources.');
} else {
  await writeFile(new URL('index.html', root), updated);
  console.log('Homepage styles synchronized.');
}
